$ErrorActionPreference = 'Stop'

$project = 'C:\xampp\htdocs\PRO\synrcypro-laravel'
$target = Join-Path $project 'resources\views\admin-all\dashboard.blade.php'
$stamp = Get-Date -Format 'yyyyMMdd-HHmmss'

Write-Host ''
Write-Host '============================================================' -ForegroundColor Cyan
Write-Host ' SYNRGYPRO - REMOVE DASHBOARD FILTER NOTE' -ForegroundColor Cyan
Write-Host '============================================================' -ForegroundColor Cyan
Write-Host ''

if (-not (Test-Path (Join-Path $project 'artisan'))) {
    throw "Project Laravel tidak ditemukan: $project"
}

if (Test-Path $target) {
    Copy-Item $target "$target.bak-$stamp" -Force
    Write-Host "BACKUP dashboard.blade.php -> .bak-$stamp" -ForegroundColor DarkYellow
}

[System.IO.File]::WriteAllBytes(
    $target,
    [System.Convert]::FromBase64String('')
)

Write-Host 'OK: dashboard.blade.php' -ForegroundColor Green

Push-Location $project
try {
    & php artisan view:clear
    & php artisan optimize:clear
}
finally {
    Pop-Location
}

Write-Host ''
Write-Host 'INSTALL SELESAI' -ForegroundColor Green
Write-Host 'Buka http://127.0.0.1:8000/admin-all lalu Ctrl + F5.' -ForegroundColor Yellow
